"""Dockerfile and .dockerignore for each app type."""

import json
from pathlib import Path

from ..source import package_json

HEADER = "# Generated by builder {version}. Do not edit by hand; change builder-spec.json and run `builder generate`.\n"
SERVE_DIR = "/usr/share/nginx/html"

_IGNORE_COMMON = """\
# Generated by builder. Keeps local state and secrets out of the image.
# Secrets and junk are matched at any depth; builder-owned and VCS paths only at the context root.
.git
.github
.venv
venv
**/node_modules
**/__pycache__
**/*.pyc
**/.env
**/.env.*
**/*.pem
**/*.key
**/*.p12
**/*.pfx
**/id_rsa*
**/.npmrc
**/.pypirc
**/.netrc
**/.aws
**/.ssh
**/secrets
deploy
Dockerfile
.dockerignore
builder-spec.json
.builder.lock
"""

# A static site served straight from its source directory has no use for project metadata.
_IGNORE_STATIC_PLAIN = """\
package.json
package-lock.json
*.md
.gitignore
"""


def _builds(root: Path) -> bool:
    pkg = package_json(root)
    return pkg is not None and "build" in pkg.get("scripts", {})


def dockerignore(spec: dict, root: Path) -> str:
    if spec["app_type"] == "static" and not _builds(root):
        return _IGNORE_COMMON + _IGNORE_STATIC_PLAIN
    return _IGNORE_COMMON


def python_command(spec: dict) -> list[str]:
    port = str(spec["port"])
    if spec["entrypoint"].endswith(".py"):
        return ["python", spec["entrypoint"]]
    target = "_platform.entry:app" if spec.get("authz") else spec["entrypoint"]
    if spec["server"] == "uvicorn":
        return ["python", "-m", "uvicorn", target, "--host", "0.0.0.0", "--port", port]
    return ["python", "-m", "gunicorn", "--header-map", "refuse", "--bind", f"0.0.0.0:{port}", target]


def node_command(spec: dict) -> list[str]:
    preload = ["--require", "./_platform/authz.js"] if spec.get("authz") else []
    return [*preload, spec["entrypoint"]]


def _python(spec: dict, img: dict) -> str:
    uid, port = img["uid"], spec["port"]
    return f"""FROM {img['build']} AS build
ENV PIP_NO_CACHE_DIR=1 PIP_DISABLE_PIP_VERSION_CHECK=1
WORKDIR /app
COPY requirements.txt .
RUN python -m venv /opt/venv && /opt/venv/bin/pip install --require-hashes -r requirements.txt
COPY . .

FROM {img['runtime']}
RUN groupadd --gid {uid} app && useradd --uid {uid} --gid {uid} --no-create-home --shell /usr/sbin/nologin app
ENV PATH=/opt/venv/bin:$PATH PYTHONDONTWRITEBYTECODE=1 PYTHONUNBUFFERED=1 PORT={port}
COPY --from=build /opt/venv /opt/venv
COPY --from=build /app /app
WORKDIR /app
USER {uid}:{uid}
EXPOSE {port}
CMD {json.dumps(python_command(spec))}
"""


def _node(spec: dict, img: dict) -> str:
    uid, port = img["uid"], spec["port"]
    return f"""FROM {img['build']} AS build
ENV NODE_ENV=production
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --omit=dev --ignore-scripts
COPY . .

FROM {img['runtime']}
ENV NODE_ENV=production PORT={port}
WORKDIR /app
COPY --from=build /app /app
USER {uid}:{uid}
EXPOSE {port}
CMD {json.dumps(node_command(spec))}
"""


def _static(spec: dict, root: Path, img: dict) -> str:
    uid, entry = img["uid"], spec["entrypoint"]
    if _builds(root):
        return f"""FROM {img['build']} AS build
WORKDIR /app
COPY package.json package-lock.json ./
RUN npm ci --ignore-scripts
COPY . .
RUN npm run build

FROM {img['runtime']}
COPY --from=build /app/{entry}/ {SERVE_DIR}/
USER {uid}:{uid}
EXPOSE 8080
"""
    return f"""FROM {img['runtime']}
COPY {entry}/ {SERVE_DIR}/
USER {uid}:{uid}
EXPOSE 8080
"""


def render_dockerfile(spec: dict, root: Path, version: str, images: dict) -> str:
    img = images[spec["app_type"]]
    if spec["app_type"] == "python":
        body = _python(spec, img)
    elif spec["app_type"] == "node":
        body = _node(spec, img)
    else:
        body = _static(spec, root, img)
    return HEADER.format(version=version) + body
